    static List<Integer>[] createAdj(int n) {
        List<Integer>[] adj = new ArrayList[n + 1];
        for (int i = 0; i <= n; i++) {
            adj[i] = new ArrayList<>();
        }
        return adj;
    }

    static int findCenter(int n, List<Integer>[] adj) {
        int[] dist = new int[n + 1];
        int[] parent = new int[n + 1];

        int a = bfs(1, n, adj, dist, null);
        int b = bfs(a, n, adj, dist, parent);

        int len = dist[b];
        int cur = b;

        for (int i = 0; i < len / 2; i++) {
            cur = parent[cur];
        }

        return cur;
    }

    static int bfs(int start, int n, List<Integer>[] adj, int[] dist, int[] parent) {
        Arrays.fill(dist, -1);
        if (parent != null) {
            Arrays.fill(parent, 0);
        }

        int[] queue = new int[n + 1];
        int head = 0, tail = 0;

        dist[start] = 0;
        queue[tail++] = start;

        int farthest = start;

        while (head < tail) {
            int u = queue[head++];
            for (int v : adj[u]) {
                if (dist[v] == -1) {
                    dist[v] = dist[u] + 1;
                    if (parent != null) {
                        parent[v] = u;
                    }
                    queue[tail++] = v;

                    if (dist[v] > dist[farthest]) {
                        farthest = v;
                    }
                }
            }
        }

        return farthest;
    }
}
